class PackedGeneratedBindingStabilityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@ValueSource(strings = { "live", "clone", "detached", "family" })
	void generatedFiniteAlternativeRetainsItsAuditedRows(String boundary) {
		TupleExpr source = finiteFilter();
		PackedQuery query = boundary.equals("family") ? PackedQueryFamilyIdentity.create(source, null).concreteQuery()
				: PackedQueryCodec.encodeForPlanning(boundary.equals("clone") ? source.clone() : source);
		if (boundary.equals("detached")) {
			query = query.withoutOriginalBindingSets();
		}
		int generated = 0;
		for (int relation = 1; relation <= query.relationCount(); relation++) {
			if (query.relOperator(relation) != PackedRelOp.BINDING_SET_ASSIGNMENT
					|| query.isOriginalBindingSetRelation(relation)) {
				continue;
			}
			generated++;
			assertTrue(query.relationReplayIsSafe(relation), "the existing generated replay proof must be available");
			BindingSetAssignment materialized = (BindingSetAssignment) PackedPlanMaterializer.materialize(query,
					relation);
			assertEquals(Set.of("s"), materialized.getBindingNames());
			assertEquals(List.of(VF.createIRI("urn:generated:a"), VF.createIRI("urn:generated:b")),
					values(materialized, "s"));
			assertTrue(BindingSetAssignmentKeyability.canInspect(materialized),
					"owned generated constants must compose stable rows at " + boundary);
			assertTrue(BindingSetAssignmentKeyability.canInspect(materialized.clone()));
		}
		assertTrue(generated > 0, "the real finite FILTER rule must generate an alternative");
	}

	@ParameterizedTest
	@ValueSource(strings = { "duplicates", "undef", "empty" })
	void detachedAuditedRowsKeepTheirExactContent(String content) {
		Value shared = VF.createIRI("urn:generated:shared");
		List<String> names = List.of("x", "nullable");
		List<BindingSet> rows = content.equals("empty") ? List.of()
				: List.of(new ListBindingSet(names, shared, content.equals("undef") ? null : shared),
						new ListBindingSet(names, shared, content.equals("undef") ? null : shared));
		BindingSetAssignment source = assignment(rows);
		PackedQuery query = PackedQueryCodec.encode(source).withoutOriginalBindingSets();
		assertTrue(query.relationReplayIsSafe(query.rootRelId()));
		BindingSetAssignment output = (BindingSetAssignment) PackedPlanMaterializer.materialize(query,
				query.rootRelId());
		assertEquals(source.getBindingNames(), output.getBindingNames());
		List<BindingSet> actual = new ArrayList<>();
		output.getBindingSets().forEach(actual::add);
		assertEquals(rows, actual);
		for (BindingSet row : actual) {
			assertSame(shared, row.getValue("x"));
		}
		assertTrue(BindingSetAssignmentKeyability.canInspect(output));
	}

	@ParameterizedTest
	@ValueSource(strings = { "mutable", "custom", "set" })
	void originalUnsafeSourcesCannotGainTrustWhenTheirSidecarIsDetached(String kind) {
		MapBindingSet mutable = new MapBindingSet();
		mutable.setBinding("x", VF.createLiteral("value"));
		BindingSet stable = new ListBindingSet(List.of("x"), VF.createLiteral("value"));
		BindingSetAssignment source = kind.equals("custom") ? new CustomAssignment() : new BindingSetAssignment();
		source.setBindingNames(Set.of("x"));
		Iterable<BindingSet> rows = kind.equals("mutable") ? List.of(mutable)
				: kind.equals("set") ? Set.of(stable) : List.of(stable);
		source.setBindingSets(rows);
		PackedQuery query = PackedQueryCodec.encode(source);
		assertFalse(query.relationReplayIsSafe(query.rootRelId()));
		BindingSetAssignment attached = (BindingSetAssignment) PackedPlanMaterializer.materialize(query,
				query.rootRelId());
		assertSame(rows, attached.getBindingSets());
		PackedQuery detached = query.withoutOriginalBindingSets();
		assertFalse(detached.relationReplayIsSafe(detached.rootRelId()));
		BindingSetAssignment reconstructed = (BindingSetAssignment) PackedPlanMaterializer.materialize(detached,
				detached.rootRelId());
		assertEquals(values(source, "x"), values(reconstructed, "x"));
		assertFalse(BindingSetAssignmentKeyability.canInspect(reconstructed));
	}

	@Test
	void explicitRepeatableSourceKeepsItsAuditedContractAfterDetachment() {
		BindingSet row = new ListBindingSet(List.of("x"), VF.createLiteral("stable"));
		BindingSetAssignment.RepeatableBindingSetSource rows = () -> List.of(row).iterator();
		BindingSetAssignment source = new BindingSetAssignment();
		source.setBindingNames(Set.of("x"));
		source.setBindingSets(rows);
		PackedQuery query = PackedQueryCodec.encode(source);
		assertTrue(query.relationReplayIsSafe(query.rootRelId()));
		assertSame(rows,
				((BindingSetAssignment) PackedPlanMaterializer.materialize(query, query.rootRelId())).getBindingSets());
		PackedQuery detached = query.withoutOriginalBindingSets();
		assertTrue(BindingSetAssignmentKeyability.canInspect(
				(BindingSetAssignment) PackedPlanMaterializer.materialize(detached, detached.rootRelId())));
	}

	@Test
	void unknownSourceRemainsUnopened() {
		AtomicInteger opens = new AtomicInteger();
		BindingSetAssignment source = new BindingSetAssignment();
		source.setBindingNames(Set.of("x"));
		source.setBindingSets(() -> {
			opens.incrementAndGet();
			throw new AssertionError("unknown sources must not be opened by encoding");
		});
		assertThrows(UnsupportedCascadesOperatorException.class, () -> PackedQueryCodec.encode(source));
		assertEquals(0, opens.get());
	}

	@Test
	void auditedOriginalSidecarsRetainIdentityThroughColdAndHotRecipes() {
		BindingSet row = new ListBindingSet(List.of("x"), VF.createLiteral("same"));
		BindingSetAssignment source = assignment(List.of(row));
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L);
		PackedPlanningResult cold = PackedCascadesPlanner.optimize(source.clone(), PackedPlannerLimits.unbounded(),
				cache, context);
		PackedPlanningResult hot = PackedCascadesPlanner.optimize(source.clone(), PackedPlannerLimits.unbounded(),
				cache, context);
		assertTrue(hot.metrics().planCacheHit());
		for (PackedPlanningResult result : List.of(cold, hot)) {
			assertTrue(result.selectedPlan() instanceof BindingSetAssignment);
			BindingSetAssignment output = (BindingSetAssignment) result.selectedPlan();
			assertSame(row, output.getBindingSets().iterator().next());
			assertTrue(BindingSetAssignmentKeyability.canInspect(output));
		}
	}

	private static TupleExpr finiteFilter() {
		return new Filter(new StatementPattern(Var.of("s"), Var.of("p", VF.createIRI("urn:generated:p")), Var.of("o")),
				new Or(new Compare(Var.of("s"), new ValueConstant(VF.createIRI("urn:generated:a")),
						Compare.CompareOp.EQ),
						new Compare(Var.of("s"), new ValueConstant(VF.createIRI("urn:generated:b")),
								Compare.CompareOp.EQ)));
	}

	private static BindingSetAssignment assignment(List<BindingSet> rows) {
		BindingSetAssignment source = new BindingSetAssignment();
		source.setBindingNames(new LinkedHashSet<>(List.of("x", "nullable")));
		source.setBindingSets(rows);
		return source;
	}

	private static List<Value> values(BindingSetAssignment assignment, String name) {
		List<Value> result = new ArrayList<>();
		assignment.getBindingSets().forEach(row -> result.add(row.getValue(name)));
		return result;
	}

	private static final class CustomAssignment extends BindingSetAssignment {
		private static final long serialVersionUID = 1L;
	}
}
